window.products.push({"id":331270,"name":"Holy Land Market Gold Shin with Sealed Glass in Olive Wood Mezuzah (19cm or  7.5 inches) Comes with Scroll Inside","category":"homeandappliances","retail price":16.53,"sale price":null,"image":"https://m.media-amazon.com/images/I/41WpoPUxDlL._AC_.jpg","description":"Olivewood, Sealed Scroll Olive wood mezuzah, 7.5 inches high, scroll sealed inside. Comes with double sticker on back to us instead of screws if needed. Olivewood, Sealed Scroll Olive wood mezuzah, 7.5 inches high, scroll sealed inside. Comes with double sticker on back to us instead of screws if needed. The mezuzah has always been both a device for remembrance by the Jewish people and a means of identifying the Jewish dwelling as a place where God is honored and revered. The mezuzah is affixed on the doorpost on the right side of the door at about eye-level (about one third of the way down from the top of the door). It is always inclined slightly inwardly (because even God's Word bows before the Creator). In order to increase the mnemonic value of the mezuzah, one is placed on the entrance of every door in a house (except those for closets and toilets).","images":["https://m.media-amazon.com/images/I/41WpoPUxDlL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Holy Land Market","source_asin":"B00GOOFUGU","category_path":"Home & Kitchen"},"sku":"BM-331270","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00GOOFUGU","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00GOOFUGU","price_pending":true,"merchant_ready":false});
